import os, requests as _requests

def _load_av_key():
    """Load Alpha Vantage API key from env var, file, or st.secrets.

    Order of precedence:
      1. AV_API_KEY environment variable
      2. ~/av_key.txt or av_key.txt next to app.py
      3. st.secrets["ALPHA_VANTAGE_API_KEY"]
    Returns None if no key is configured. NEVER hardcode a key here —
    a leaked key gets the entire user base rate-limited.
    """
    # Try environment variable first
    key = os.environ.get("AV_API_KEY", "").strip()
    if key and key not in ("demo",""):
        return key
    # Try key file next to app.py
    for path in [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "av_key.txt"),
        os.path.expanduser("~/av_key.txt"),
    ]:
        try:
            with open(path) as f:
                key = f.read().strip()
                if key and key not in ("demo",""):
                    return key
        except Exception:
            pass
    # Try st.secrets
    try:
        k = st.secrets.get("ALPHA_VANTAGE_API_KEY")
        if k and str(k).strip() not in ("demo", ""):
            return str(k).strip()
    except Exception:
        pass
    # No key configured — Alpha Vantage features will be disabled
    return None

_AV_KEY = _load_av_key()
_AV_AVAILABLE = _AV_KEY is not None


def _load_anthropic_key():
    """Anthropic API key for the statement-import feature.
    Order: ANTHROPIC_API_KEY env var → anthropic_key.txt → st.secrets.
    Returns None if not configured (feature shows setup instructions)."""
    key = os.environ.get("ANTHROPIC_API_KEY", "").strip()
    if key:
        return key
    for path in [
        os.path.join(os.path.dirname(os.path.abspath(__file__)), "anthropic_key.txt"),
        os.path.expanduser("~/anthropic_key.txt"),
    ]:
        try:
            with open(path) as f:
                k = f.read().strip()
                if k:
                    return k
        except Exception:
            pass
    try:
        k = st.secrets.get("ANTHROPIC_API_KEY")
        if k and str(k).strip():
            return str(k).strip()
    except Exception:
        pass
    return None


def _anthropic_model():
    """Model used for statement extraction; overridable via secrets/env."""
    try:
        m = st.secrets.get("ANTHROPIC_MODEL")
        if m and str(m).strip():
            return str(m).strip()
    except Exception:
        pass
    return os.environ.get("ANTHROPIC_MODEL", "").strip() or "claude-sonnet-4-6"


